from datetime import date
from collections.abc import Iterable

def allocate_fefo(
    batches: Iterable[dict],
    requested_units: int,
    today: date,
) -> tuple[list[dict], int]:
    if requested_units < 0:
        raise ValueError("requested_units must be non-negative")

    remaining = requested_units
    allocations = []
    eligible = sorted(
        (
            batch
            for batch in batches
            if batch["on_hand"] > 0 and batch["expires_on"] >= today
        ),
        key=lambda batch: (batch["expires_on"], batch["batch_id"]),
    )
    for batch in eligible:
        if remaining == 0:
            break

        picked = min(batch["on_hand"], remaining)
        allocations.append(
            {
                "batch_id": batch["batch_id"],
                "quantity": picked,
                "expires_on": batch["expires_on"],
            }
        )
        remaining -= picked

    return allocations, remaining

